  attend_mode, place, online_link, capacity, budget_planned, budget_other, budget_actual,
  ask_dietary, meals, issue_certificate, refund_method, status, cycle_stage,
  cert_signer_name, cert_signer_title, email_on_register, email_before_event, email_after_event, created_at)
