-- ------------------------------------------------------------------ who has signed up so far (year 3+, not suspended)
INSERT INTO registrations (id, event_id, user_id, dept, status, attend_via, registered_at)
SELECT 106300 + ROW_NUMBER() OVER (ORDER BY u.id), 1063, u.id, u.dept, 'registered', 'onsite',
       TIMESTAMP('2026-10-16' + INTERVAL (u.id % 30) DAY, '20:10:00')
FROM users u
WHERE u.role = 'student'
  AND CAST(REGEXP_SUBSTR(u.dept, '[0-9]+') AS UNSIGNED) >= 3
  AND u.id % 2 = 0
  AND NOT EXISTS (SELECT 1 FROM blacklist_entries b WHERE b.user_id = u.id AND b.restored_at IS NULL);

-- ------------------------------------------------------------------ the poster (JPEG, padded to 1124 x 1498, 3:4)
UPDATE events SET poster_url = 'data:image/jpeg;base64,' WHERE id = 1063;
